Lemma head : PMU.locale_ctor_spec L HI ->
  forall (fx : FPState) R0 M0 model0 K LB cr ois os sp r s b,
    PMISU.pre L HI R0 M0 model0 K LB cr ois os sp r s b ->
    (forall (fx1 : FPState) R1 M1 model1, PMISU.mid L HI R0 M0 model0 LB cr ois os sp s b R1 M1 model1 ->
        srealizes RSEGS SCFG (@PMSP.cfg RSEGS fx1 R1 0x359f4 M1 model1) K) ->
    srealizes RSEGS SCFG (@PMSP.cfg RSEGS fx R0 0x351ec M0 model0) K.
Proof.
